<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarProveedor, guardarProveedor, listarProveedores, type Proveedor } from '../services/proveedores'
const rows=ref<Proveedor[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive({ruc:'',razon_social:'',celular:'',telefono_fijo:'',email:'',direccion:'',estado:true})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const response=await listarProveedores(criterio.value,next);rows.value=response.data;total.value=response.total;lastPage.value=response.last_page}catch(cause){error.value=message(cause)}finally{loading.value=false}}
function open(item?:Proveedor){editing.value=item?.id||null;Object.assign(form,{ruc:item?.ruc||'',razon_social:item?.razon_social||'',celular:item?.celular||'',telefono_fijo:item?.telefono_fijo||'',email:item?.email||'',direccion:item?.direccion||'',estado:item?.estado??true});modal.value=true}
function validate(){if(!/^\d{11}$/.test(form.ruc))return 'El RUC debe contener exactamente 11 dígitos.';if(form.razon_social.trim().length<2)return 'Ingrese la razón social.';if(!/^\d{9}$/.test(form.celular))return 'El celular debe contener exactamente 9 dígitos.';if(form.telefono_fijo&&!/^\d+$/.test(form.telefono_fijo))return 'El teléfono fijo solo debe contener números.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email))return 'Ingrese un correo electrónico válido.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarProveedor(editing.value,{...form});success.value='Proveedor guardado correctamente.';modal.value=false;await load(editing.value?page.value:1)}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function remove(item:Proveedor){if(item.procesos_count||item.ordenes_count){error.value='El proveedor tiene procesos u órdenes asociados y no puede eliminarse.';return}if(!confirm(`¿Eliminar al proveedor “${item.razon_social}”?`))return;try{await eliminarProveedor(item.id);success.value='Proveedor eliminado correctamente.';await load(page.value)}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Proveedores</nav><header class="hero"><div class="mark">PR</div><div><small>MIA · Logística</small><h1>Proveedores</h1><p>Administra los datos fiscales y de contacto de proveedores.</p></div><strong>{{total}} proveedores</strong><button @click="open()">+ Nuevo proveedor</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por RUC o razón social…" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="clear" @click="criterio='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando proveedores…</div><div v-else-if="!rows.length" class="empty">No se encontraron proveedores.</div><section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{inactive:item.estado===false}"><header><div class="avatar">{{item.razon_social.slice(0,2).toUpperCase()}}</div><div><small>RUC {{item.ruc}}</small><h2>{{item.razon_social}}</h2></div><em>{{item.estado===false?'Inactivo':'Activo'}}</em></header><dl><div><dt>Correo</dt><dd>{{item.email||'—'}}</dd></div><div><dt>Celular</dt><dd>{{item.celular||'—'}}</dd></div><div><dt>Teléfono fijo</dt><dd>{{item.telefono_fijo||'—'}}</dd></div><div><dt>Dirección</dt><dd>{{item.direccion||'—'}}</dd></div></dl><section class="metrics"><div><b>{{item.procesos_count||0}}</b><span>Procesos</span></div><div><b>{{item.ordenes_count||0}}</b><span>Órdenes</span></div></section><footer><button @click="open(item)">Editar</button><button class="delete" :disabled="Boolean(item.procesos_count||item.ordenes_count)" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>Proveedor logístico</small><h2>{{editing?'Editar':'Registrar'}} proveedor</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>RUC *<input v-model.trim="form.ruc" inputmode="numeric" maxlength="11"></label><label>Razón social *<input v-model.trim="form.razon_social" maxlength="255"></label><label>Celular *<input v-model.trim="form.celular" inputmode="numeric" maxlength="9"></label><label>Teléfono fijo<input v-model.trim="form.telefono_fijo" inputmode="numeric"></label><label>Correo electrónico *<input v-model.trim="form.email" type="email"></label><label>Dirección<input v-model.trim="form.direccion"></label></div><label class="check"><input v-model="form.estado" type="checkbox"> Proveedor activo</label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar proveedor'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.modal small,.cards small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.35rem}.hero p{margin:0;color:#7d898f;font-size:.7rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:11px;display:flex;gap:7px;border-radius:9px;background:#fff}.filters input{flex:1}input{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.clear{color:#68757c!important;background:#edf1f3!important}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:14px;border:1px solid #e0e5e8;border-top:4px solid var(--accent);border-radius:9px;background:#fff}.cards article.inactive{opacity:.65;border-top-color:#9da7ac}.cards article>header{display:flex;align-items:center;gap:8px}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:9px;color:var(--accent);background:#f8e9ef;font-size:.62rem;font-weight:700}.cards h2{margin:2px 0;font-size:.68rem}.cards header em{margin-left:auto;padding:4px 7px;border-radius:9px;background:#e8f7ef;font-size:.48rem;font-style:normal}.cards dl{margin:12px 0}.cards dl>div{padding:5px 0;display:flex;border-bottom:1px solid #edf0f2;font-size:.53rem}.cards dt{color:#7d898f}.cards dd{margin-left:auto;text-align:right}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.metrics div{padding:7px;text-align:center;border-radius:6px;background:#f4f6f7}.metrics b,.metrics span{display:block;font-size:.5rem}.metrics b{font-size:.7rem}.cards footer{margin-top:10px;display:flex}.cards footer button{border:0;color:var(--accent);background:none;font-size:.53rem}.cards footer .delete{margin-left:auto;color:#b44747}.cards footer button:disabled{color:#abb2b5}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,650px);padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0 14px;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.modal label{display:block;margin-bottom:9px;font-size:.55rem}.check input{width:auto}.modal footer{display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.cards{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}
</style>
